package com.cpf.education.online.externalsideeffect.controller;
import com.cpf.core.api.result.CpfResult; import com.cpf.education.online.externalsideeffect.dto.PaymentCommand; import com.cpf.education.online.externalsideeffect.service.PaymentService; import com.cpf.foundation.execution.api.CpfOnlineTransaction; import com.cpf.web.api.CpfController; import io.swagger.v3.oas.annotations.Operation; import org.springframework.web.bind.annotation.*;
/** PaymentController는 외부 Side Effect와 Local DB Commit 결과를 분리하고 UNKNOWN을 복구로 연결하는 거래 Golden Path입니다. */
@CpfController @RequestMapping("/edu/online/payment") public class PaymentController {private final PaymentService service;public PaymentController(PaymentService service){this.service=service;}@PostMapping @Operation(operationId="EDU_PAYMENT_SIDE_EFFECT",summary="Transaction + External Side Effect") @CpfOnlineTransaction(operationId="EDU_PAYMENT_SIDE_EFFECT",name="결제 처리",description="Remote SUCCESS와 Local commit 성공을 구분하고 UNKNOWN은 Reconcile로 연결한다.") public CpfResult<String> pay(@RequestBody PaymentCommand c){return service.pay(c);}}
